  if (error.code !== 'MODULE_NOT_FOUND') {
    throw error;
  }

  express = () => {
    const routes = [];

    const app = (req, res) => {
      const path = (req.url || '').split('?')[0];
      const route = routes.find((candidate) => (
        candidate.method === req.method && candidate.path === path
      ));

      res.json = (body) => {
        if (!res.headersSent) {
